+            );
+        }
+        if (hasSecondaryAuthHeader) {
+            assertThat(headers1, hasKey(SecondaryAuthentication.THREAD_CTX_KEY));
+            assertThat(
+                headers1.get(SecondaryAuthentication.THREAD_CTX_KEY),
